<?php
namespace App\Services;
use App\Models\Nadu; use App\Support\CompanyContext; use App\Support\SithasiValueFormatter; use Carbon\Carbon; use PhpOffice\PhpWord\TemplateProcessor;
class BulkWibagaDinaya2Service extends BulkThinduwaWrittenService { protected function templatePath(): string{return storage_path('app/documents/2_wibaga_dinaya.docx');} protected function outputDirectoryName(): string{return 'wibaga-dinaya-2';} protected function filePrefix(): string{return 'wibaga_dinaya_2';} protected function documentType(): string{return 'Bulk 2 Wibaga Dinaya';} protected function fillTemplate(TemplateProcessor $t,Nadu $c,array $v=[]):void{$company=app(CompanyContext::class)->company(); $date=SithasiValueFormatter::dateParts($company?->wibhaga_dinaya); foreach(['2_wibaga_dinaya_block'=>'','/2_wibaga_dinaya_block'=>'','නඩු_අංකය_ format '=>$company?->nadu_ankaya_format,'දිනය'=>$date['dinaya'],'වරුව'=>SithasiValueFormatter::waruwa($company?->welawa),'වෙලාව'=>SithasiValueFormatter::time($company?->welawa),'නියෝජිත'=>$company?->niyojithaya,'first_sithasiya_date'=>$company?->first_sithasiya_date ? Carbon::parse($company->first_sithasiya_date)->format('Y/m/d') : '','second_sithasiya_date'=>$company?->second_sithasiya_date ? Carbon::parse($company->second_sithasiya_date)->format('Y/m/d') : '',' නඩු_අංකය'=>$c->nadu_ankaya,'ණයකරු_1'=>$c->nayakaru1_nama,'ණයකරු_2'=>$c->nayakaru2_nama,'ඇපකරු_1'=>$c->aepakaru1_nama,'ඇපකරු_2'=>$c->aepakaru2_nama] as $k=>$x)$t->setValue($k,$x??'');}}
